logger: logging.Logger = logging.getLogger(__name__)

DOTENV_MODULE: Any | None
try:
    DOTENV_MODULE = importlib.import_module("dotenv")
except ImportError:
    DOTENV_MODULE = None


def load_shared_environment() -> bool:
    """Laedt die geteilte Umgebungskonfiguration aus .env.shared.

    Durchsucht eine Prioritaetsliste von Pfaden nach einer .env.shared-datei
    und laedt die erste gefundene.

    Returns:
        True wenn eine Konfigurationsdatei geladen wurde, False wenn keine gefunden wurde.
    """
    shared_env_paths: list[str | Path] = [
        r"\\srv-zen-fs-01.aschendorff.de\anzeigen\dbm\Vertriebsverkauf\11_ESUITE_D6\Python\env\.env.shared",
        Path.home() / ".env.shared",
        ".env.shared",
        ".env",
    ]

    for env_path in shared_env_paths:
        if os.path.exists(env_path):
            if DOTENV_MODULE is None:
                logger.info("python-dotenv ist nicht verfuegbar: %s", env_path)
                return False
            DOTENV_MODULE.load_dotenv(env_path)
            logger.info("Shared config geladen von: %s", env_path)
            return True

    logger.info("Keine .env.shared gefunden - verwende Systemumgebungsvariablen")
    return False


