def __getattr__(name: str) -> Any:
    """Stellt alte secret-haltige Konstantennamen lazy bereit."""
    from .config_service import (
        get_database_config,
        get_esuite_headers,
        get_sftp_account_config,
        get_sftp_bdl_import_config,
        get_sftp_esuite_config,
        get_sftp_order_config,
        get_sftp_vsg_dummy_import_config,
        get_sftp_vsg_hanseatic_import_config,
    )

    if name == "HEADERS_PROD":
        return get_esuite_headers("PROD")
    if name == "HEADERS_UAT":
        return get_esuite_headers("UAT")

    if name in {"DB_HOST", "DB_PORT", "DB_USER", "DB_PASSWORD"}:
        db_config = get_database_config()
        values: dict[str, str | int] = {
            "DB_HOST": db_config.host,
            "DB_PORT": db_config.port,
            "DB_USER": db_config.user,
            "DB_PASSWORD": db_config.password,
        }
        return values[name]

    sftp_getters = {
        "ACC": get_sftp_account_config,
        "ORD": get_sftp_order_config,
        "ESUITE": get_sftp_esuite_config,
        'BDL':get_sftp_bdl_import_config,
        'VSG_DUMMY':get_sftp_vsg_dummy_import_config,
        'VSG_HANSEATIC':get_sftp_vsg_hanseatic_import_config,
    }
    for suffix, getter in sftp_getters.items():
        if name in {
            f"SFTP_HOST_{suffix}",
            f"SFTP_PORT_{suffix}",
            f"SFTP_USERNAME_{suffix}",
            f"SFTP_PASSWORD_{suffix}",
        }:
            sftp_config = getter()
            values = {
                f"SFTP_HOST_{suffix}": sftp_config.host,
                f"SFTP_PORT_{suffix}": sftp_config.port,
                f"SFTP_USERNAME_{suffix}": sftp_config.username,
                f"SFTP_PASSWORD_{suffix}": sftp_config.password,
            }
            return values[name]

    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")
